using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver so metadata is auto-created for
// types the serializer encounters (reflection-based).
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// ---------------------------------------------------------------
// 1. Strongly-typed retrieval — JsonTypeInfo<T> via the generic
//    overload of GetTypeInfo<T>().
// ---------------------------------------------------------------
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();

Console.WriteLine("=== Strongly-typed metadata ===");
Console.WriteLine($"Type       : {typedInfo.Type.Name}");
Console.WriteLine($"Kind       : {typedInfo.Kind}");
Console.WriteLine($"Properties : {typedInfo.Properties.Count}");
foreach (var prop in typedInfo.Properties)
    Console.WriteLine($"  - {prop.Name} ({prop.PropertyType.Name})");

// Quick round-trip to prove the typed info works.
var forecast = new WeatherForecast("Seattle", 18.5, DateTime.UtcNow);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"\nSerialized : {json}");

WeatherForecast? deserialized = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Deserialized: {deserialized}");

// ---------------------------------------------------------------
// 2. Probe-without-throwing — TryGetTypeInfo returns false when
//    metadata for the requested type cannot be resolved, instead
//    of throwing InvalidOperationException.
// ---------------------------------------------------------------
Console.WriteLine("\n=== TryGetTypeInfo (probe without throwing) ===");

// This type IS resolvable (already resolved above).
if (options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info1))
    Console.WriteLine($"WeatherForecast : resolved  -> {info1!.Type.Name}");
else
    Console.WriteLine("WeatherForecast : NOT resolved");

// Use a resolver that resolves *nothing*, so the probe returns false
// instead of throwing.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new NullResolver()
};

if (emptyOptions.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info2))
    Console.WriteLine($"WeatherForecast (empty resolver): resolved  -> {info2!.Type.Name}");
else
    Console.WriteLine("WeatherForecast (empty resolver): NOT resolved  (no exception thrown!)");

// ---------------------------------------------------------------
// Supporting types
// ---------------------------------------------------------------
record WeatherForecast(string City, double TemperatureC, DateTime Date);

/// <summary>A resolver that intentionally resolves nothing.</summary>
sealed class NullResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

